/// Descriptor with the given JSON path, or nullptr.
constexpr const ParamDescriptor* find_param(std::string_view path) noexcept {
  for (const ParamDescriptor& d : kParamDescriptors) {
    if (d.path == path) {
      return &d;
    }
  }
  return nullptr;
}

